import SXCore

public enum YamahaVoices {
    public static func melodicProgram(_ voice: Style.VoiceAddress, guitar: Bool = false, bass: Bool = false) -> UInt8 {
        if voice.msb == 8 && voice.lsb < 16 {
            switch voice.program {
            case 0: return 24
            case 1, 2: return 25
            case 3: return 27
            case 4: return 29
            case 5: return 30
            case 6: return 26
            case 16...19: return voice.program + 16
            default: break
            }
        }
        if guitar && !(24...31).contains(voice.program) { return voice.program == 5 && voice.msb == 8 ? 30 : 25 }
        if bass && !(32...39).contains(voice.program) { return 33 }
        return voice.program
    }

    public static func drumProgram(_ voice: Style.VoiceAddress) -> UInt8 {
        guard voice.msb == 127 else { return voice.msb == 126 ? 56 : 0 }
        switch Int(voice.program) + 1 {
        case 9...16: return 8
        case 17...24, 70, 73, 74, 91, 92: return 16
        case 25...28, 57...62, 67...69, 71...72: return 24
        case 33...40: return 32
        case 41, 42, 76: return 40
        case 49: return 48
        default: return 0
        }
    }

    public static func drumNote(_ note: UInt8, voice: Style.VoiceAddress) -> UInt8 {
        guard voice.msb == 126 || voice.msb == 127 else { return note }
        let key = Int(voice.msb) << 14 | Int(voice.lsb) << 7 | Int(voice.program)
        if let mapped = drumNotes[key]?[note] { return mapped }
        return note
    }

